void Loader_clipMap_t::LoadPtr_clipMap_t(const bool atStreamStart)
{
    assert(varclipMap_tPtr != nullptr);
    
    assert(!atStreamStart);
    
    m_stream.PushBlock(XFILE_BLOCK_TEMP);
    
    if (*varclipMap_tPtr != nullptr)
    {
        const auto zonePtrType = GetZonePointerType(*varclipMap_tPtr);
        if (zonePtrType == ZonePointerType::FOLLOWING || zonePtrType == ZonePointerType::INSERT)
        {
            *varclipMap_tPtr = m_stream.AllocOutOfBlock<clipMap_t>(4);
            
            uintptr_t toInsertLookupEntry = 0;
            if (zonePtrType == ZonePointerType::INSERT)
                toInsertLookupEntry = m_stream.InsertPointerAliasLookup();
            
            varclipMap_t = *varclipMap_tPtr;
            Load_clipMap_t(true);
            
            LoadAsset_clipMap_t(varclipMap_tPtr);
            
            if (zonePtrType == ZonePointerType::INSERT)
                m_stream.SetInsertedPointerAliasLookup(toInsertLookupEntry, *varclipMap_tPtr);
        }
        else
        {
            *varclipMap_tPtr = m_stream.ConvertOffsetToAliasLookup(*varclipMap_tPtr);
        }
    }
    
    m_stream.PopBlock();
}

void Loader_clipMap_t::LoadAsset_clipMap_t(clipMap_t** pAsset)
{
    assert(pAsset != nullptr);
    
    AssetInfoCollector assetInfo(m_zone);
    AssetMarker<AssetClipMapPvs> marker(assetInfo);
    marker.Mark(*pAsset);
    
    auto* reallocatedAsset = m_zone.Memory().Alloc<clipMap_t>();
    std::memcpy(reallocatedAsset, *pAsset, sizeof(clipMap_t));
    
    m_asset_info = reinterpret_cast<XAssetInfo<clipMap_t>*>(LinkAsset(AssetName<AssetClipMapPvs>(**pAsset), reallocatedAsset, assetInfo.GetDependencies(), assetInfo.GetUsedScriptStrings(), assetInfo.GetIndirectAssetReferences()));
    *pAsset = m_asset_info->Asset();
}
